// Restaura objetos Date dentro dos calendários guardados (JSON não preserva o tipo Date).
function reviveDrawsDates(draws) {
  const fix = (cal) => (cal ? { ...cal, jornadas: cal.jornadas.map((j) => ({ ...j, data: new Date(j.data) })) } : cal);
  const revived = {};
  Object.entries(draws || {}).forEach(([compId, entry]) => {
    const next = { ...entry, calendario: fix(entry.calendario) };
    if (entry.fases) {
      next.fases = {
        ...entry.fases,
        fase2: entry.fases.fase2 ? { ...entry.fases.fase2, calendario: fix(entry.fases.fase2.calendario) } : entry.fases.fase2,
        honra: entry.fases.honra ? { ...entry.fases.honra, calendario: fix(entry.fases.honra.calendario) } : entry.fases.honra,
      };
    }
    revived[compId] = next;
  });
  return revived;
}
// ---------------------------------------------------------------------------
// Exportação para Excel — Equipas Inscritas, Calendário e Classificações,
// prontas a abrir e a partilhar tal como o vosso ficheiro atual.
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Exportações contextuais — Excel e PDF exportam apenas o que está visível no
// separador aberto (não a plataforma toda).
// ---------------------------------------------------------------------------
function linhasCalendario(comp, calendario, teamsLabeled, faseNome, draws, pedidosDesencontro) {
  const parceiro = calendarioParceiroDe(comp.id, draws || {});
  const pool = [...poolEquipas(calendario), ...poolEquipas(parceiro)];
  const autoGroups = autoDesencontroGroups(pool, teamsLabeled, pedidosDesencontro);
  const { jornadas } = applyDesencontros(calendario, autoGroups, parceiro);
  const linhas = [];
  jornadas.forEach((j) => {
    j.jogosPorSerie.forEach((sp) => {
      sp.jogos.forEach((m) => {
        linhas.push({
          Prova: comp.nome,
          Fase: faseNome,
          "Série": sp.serie || "-",
          Jornada: j.jornada,
          Data: j.data.toLocaleDateString("pt-PT"),
          Dia: comp.diaIdx === 6 ? "Sábado" : "Domingo",
          Hora: comp.hora,
          "Equipa Casa": m.homeLabel,
          "Equipa Fora": m.awayLabel,
          "Recinto": recintoDaEquipa(m.home, teamsLabeled) || "",
        });
      });
    });
  });
  return linhas;
}

function exportarEquipasExcel(lista, sufixo) {
  const rows = lista.map((t) => {
    const clube = clubeById(t.clubeId);
    const comp = compById(t.competicaoId);
    return {
      Clube: teamLabel(t),
      "Código": clube.codigo,
      Concelho: CONCELHOS[clube.concelhoId]?.nome || "",
      Prova: comp.nome,
      Tipo: comp.tipo,
      "Série": t.serie || "-",
      "Recinto": t.recinto || "",
      Estado: t.estado,
    };
  });
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), "Equipas Inscritas");
  XLSX.writeFile(wb, `AF-Beja-Equipas${sufixo ? "-" + sufixo : ""}_${new Date().toISOString().slice(0, 10)}.xlsx`);
}

function exportarCalendarioExcel(comp, faseNome, calendario, teamsLabeled, draws, pedidosDesencontro) {
  const rows = linhasCalendario(comp, calendario, teamsLabeled, faseNome, draws, pedidosDesencontro);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), "Calendário");
  XLSX.writeFile(wb, `AF-Beja-Calendario-${comp.id}_${new Date().toISOString().slice(0, 10)}.xlsx`);
}

function exportarQuadroExcel(comp, draw) {
  const rows = [];
  if (draw.modo === "grupos") {
    draw.grupos.forEach((g, gi) => g.forEach((t) => rows.push({ Prova: comp.nome, "Série": String.fromCharCode(65 + gi), Clube: teamLabel(t) })));
  } else if (draw.modo === "liga") {
    draw.liga.forEach((t, i) => rows.push({ Prova: comp.nome, "Posição": i + 1, Clube: teamLabel(t) }));
  } else if (draw.modo === "eliminatoria") {
    draw.bracket.forEach((ronda, ri) => ronda.forEach((jogo, ji) => rows.push({ Prova: comp.nome, Ronda: ri + 1, Jogo: ji + 1, Casa: jogo.a, Fora: jogo.b ?? "Isento" })));
  }
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), "Quadro");
  XLSX.writeFile(wb, `AF-Beja-Quadro-${comp.id}_${new Date().toISOString().slice(0, 10)}.xlsx`);
}

const P_PDF = { ink: "#16110F", ink2: "#5A4E48", line: "#D8CFC8", soft: "#F3EEE9" };
function PrintShell({ subtitulo, onClose, children }) {
  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" style={{ backgroundColor: "#FFFFFF" }}>
      <div className="no-print sticky top-0 z-10 flex items-center justify-between border-b px-6 py-3" style={{ backgroundColor: "#F3EEE9", borderColor: P_PDF.line }}>
        <p className="pf-body text-sm font-semibold" style={{ color: P_PDF.ink }}>Pré-visualização — {subtitulo}</p>
        <div className="flex gap-2">
          <button onClick={() => window.print()} className="pf-body flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-semibold text-white" style={{ backgroundColor: "#C13C4B" }}>
            <FileDown size={13} /> Imprimir / Guardar PDF
          </button>
          <button onClick={onClose} className="pf-body rounded-md border px-3 py-1.5 text-xs font-semibold" style={{ borderColor: P_PDF.line, color: P_PDF.ink }}>Fechar</button>
        </div>
      </div>
      <div className="print-area mx-auto max-w-3xl px-8 py-8" style={{ color: P_PDF.ink, fontFamily: "Inter, sans-serif" }}>
        <div className="flex items-center justify-between border-b-2 pb-3" style={{ borderColor: P_PDF.ink }}>
          <div>
            <p style={{ fontFamily: "Oswald, sans-serif", fontWeight: 600, fontSize: 20 }}>
              Distrital<span style={{ color: "#C13C4B" }}>Pro</span> · AF Beja
            </p>
            <p style={{ fontSize: 11, color: P_PDF.ink2 }}>{subtitulo} — Época 2026/2027</p>
          </div>
          <p style={{ fontSize: 10, color: P_PDF.ink2 }}>Gerado em {new Date().toLocaleDateString("pt-PT")} às {new Date().toLocaleTimeString("pt-PT")}</p>
        </div>
        {children}
      </div>
    </div>
  );
}

// request: { tipo: 'equipas', lista, subtitulo } | { tipo:'calendario', comp, faseNome, calendario, teamsLabeled } | { tipo:'quadro', comp, draw }
function RelatorioPDF({ request, onClose }) {
  if (!request) return null;
  if (request.tipo === "equipas") {
    return (
      <PrintShell subtitulo={request.subtitulo || "Equipas Inscritas"} onClose={onClose}>
        <table style={{ width: "100%", fontSize: 10.5, borderCollapse: "collapse", marginTop: 16 }}>
          <thead>
            <tr style={{ color: P_PDF.ink2, textAlign: "left" }}>
              <th style={{ padding: "3px 6px", fontWeight: 600 }}>Clube</th>
              <th style={{ padding: "3px 6px", fontWeight: 600 }}>Prova</th>
              <th style={{ padding: "3px 6px", fontWeight: 600 }}>Série</th>
              <th style={{ padding: "3px 6px", fontWeight: 600 }}>Recinto</th>
            </tr>
          </thead>
          <tbody>
            {request.lista.map((t) => (
              <tr key={t.id} style={{ borderTop: `1px solid ${P_PDF.line}` }}>
                <td style={{ padding: "3px 6px" }}>{teamLabel(t)}</td>
                <td style={{ padding: "3px 6px" }}>{compById(t.competicaoId).nome}</td>
                <td style={{ padding: "3px 6px" }}>{t.serie ?? "—"}</td>
                <td style={{ padding: "3px 6px" }}>{t.recinto ?? "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </PrintShell>
    );
  }
  if (request.tipo === "calendario") {
    const { comp, faseNome, calendario, teamsLabeled, draws, pedidosDesencontro } = request;
    const parceiro = calendarioParceiroDe(comp.id, draws || {});
    const pool = [...poolEquipas(calendario), ...poolEquipas(parceiro)];
    const autoGroups = autoDesencontroGroups(pool, teamsLabeled, pedidosDesencontro);
    const { jornadas } = applyDesencontros(calendario, autoGroups, parceiro);
    return (
      <PrintShell subtitulo={`Calendário · ${comp.nome}${faseNome ? " · " + faseNome : ""}`} onClose={onClose}>
        {jornadas.map((j) => (
          <div key={j.jornada} style={{ marginTop: 10 }}>
            <p style={{ fontSize: 11, fontWeight: 600 }}>
              Jornada {j.jornada} <span style={{ fontWeight: 400, color: P_PDF.ink2 }}>· {formatData(j.data)}</span>
            </p>
            {j.jogosPorSerie.map((sp) => (
              <div key={sp.serie ?? "u"} style={{ fontSize: 10.5, paddingLeft: 10 }}>
                {sp.jogos.map((m, mi) => (
                  <p key={mi} style={{ margin: "1px 0" }}>
                    {sp.serie ? `[Série ${sp.serie}] ` : ""}{m.homeLabel} – {m.awayLabel}
                    {recintoDaEquipa(m.home, teamsLabeled) && (
                      <span style={{ color: P_PDF.ink2 }}> · {recintoDaEquipa(m.home, teamsLabeled)}</span>
                    )}
                  </p>
                ))}
              </div>
            ))}
          </div>
        ))}
      </PrintShell>
    );
  }
  if (request.tipo === "quadro") {
    const { comp, draw } = request;
    return (
      <PrintShell subtitulo={`Quadro · ${comp.nome}`} onClose={onClose}>
        {draw.modo === "grupos" && draw.grupos.map((g, gi) => (
          <div key={gi} style={{ marginTop: 12 }}>
            <p style={{ fontSize: 11.5, fontWeight: 600, backgroundColor: P_PDF.soft, padding: "4px 8px", borderRadius: 4 }}>Série {String.fromCharCode(65 + gi)}</p>
            {g.map((t) => <p key={t.id} style={{ fontSize: 10.5, margin: "2px 6px" }}>{teamLabel(t)}</p>)}
          </div>
        ))}
        {draw.modo === "liga" && (
          <table style={{ width: "100%", fontSize: 10.5, borderCollapse: "collapse", marginTop: 12 }}>
            <tbody>
              {draw.liga.map((t, i) => (
                <tr key={t.id} style={{ borderTop: `1px solid ${P_PDF.line}` }}>
                  <td style={{ padding: "3px 6px", width: 30 }}>{i + 1}</td>
                  <td style={{ padding: "3px 6px" }}>{teamLabel(t)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {draw.modo === "eliminatoria" && draw.bracket.map((ronda, ri) => (
          <div key={ri} style={{ marginTop: 10 }}>
            <p style={{ fontSize: 11, fontWeight: 600 }}>{roundLabel(ri, draw.bracket.length)}</p>
            {ronda.map((jogo, ji) => <p key={ji} style={{ fontSize: 10.5, margin: "2px 0" }}>{jogo.a} – {jogo.b ?? "Isento"}</p>)}
          </div>
        ))}
      </PrintShell>
    );
  }
  return null;
}

// Dados de contacto e prazo — placeholders claramente marcados; substitua pelos
// valores reais do Gabinete Técnico assim que os tiver.
const CONFIG_PLATAFORMA = {
  emailGabinete: "gabinetetecnico@afbeja.pt",
  telefoneGabinete: "284 322 355",
  prazoInscricao: "2026-09-15",
};
const STORAGE_KEY = "af-beja-estado-2026-27-v2";

// Acesso ao Gabinete Técnico — proteção simples ao nível da interface.
// NOTA HONESTA: isto NÃO é segurança real. O código corre no browser de quem
// o abre, por isso qualquer pessoa com conhecimentos técnicos pode contornar
// esta password inspecionando a página. Serve para impedir acesso casual dos
// clubes às restantes áreas, não para proteger dados sensíveis. Para acesso
// verdadeiramente seguro (contas separadas por clube, etc.) seria preciso um
// site com autenticação a sério no servidor — fora do alcance de um artefacto.
const PASSWORD_GABINETE = "gabinete2027";

export default function App() {
  const [teams, setTeams] = useState(seedTeams);
  const teamsLabeled = useMemo(() => computeLabels(teams), [teams]);
  const [draws, setDraws] = useState(() => initialDraws(computeLabels(seedTeams)));
  const [resultados, setResultados] = useState({});
  const [publicados, setPublicados] = useState({});
  const [pedidosDesencontro, setPedidosDesencontro] = useState([]);
  const [tab, setTab] = useState("inicio");
  const [carregado, setCarregado] = useState(false);
  const [estadoGravacao, setEstadoGravacao] = useState("");
  const [modoGabinete, setModoGabinete] = useState(false);
  const [printRequest, setPrintRequest] = useState(null);
  const [mostrarLogin, setMostrarLogin] = useState(false);
  const [passwordInput, setPasswordInput] = useState("");
  const [erroLogin, setErroLogin] = useState(false);

  const tentarEntrar = () => {
    if (passwordInput === PASSWORD_GABINETE) {
      setModoGabinete(true);
      setMostrarLogin(false);
      setPasswordInput("");
      setErroLogin(false);
    } else {
      setErroLogin(true);
    }
  };
  const sairGabinete = () => {
    setModoGabinete(false);
    setTab("inicio");
  };

  // Carrega o estado guardado (partilhado por todos os que abrem esta plataforma) ao iniciar.
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY, true);
        if (res && res.value) {
          const parsed = JSON.parse(res.value);
          if (Array.isArray(parsed.clubesExtra)) {
            parsed.clubesExtra.forEach((c) => { if (!CLUBES.find((x) => x.id === c.id)) CLUBES.push(c); });
          }
          if (Array.isArray(parsed.teams)) setTeams(parsed.teams);
          if (parsed.draws) setDraws(reviveDrawsDates(parsed.draws));
          if (parsed.resultados) setResultados(parsed.resultados);
          if (parsed.publicados) setPublicados(parsed.publicados);
          if (Array.isArray(parsed.pedidosDesencontro)) setPedidosDesencontro(parsed.pedidosDesencontro);
          setEstadoGravacao("Estado anterior carregado.");
        }
      } catch (e) {
        console.error("Falha ao carregar estado guardado:", e);
      } finally {
        setCarregado(true);
      }
    })();
  }, []);

  // Grava automaticamente (com pequeno atraso) sempre que algo muda.
  useEffect(() => {
    if (!carregado) return;
    const t = setTimeout(async () => {
      try {
        const clubesExtra = CLUBES.slice(47);
        const payload = JSON.stringify({ teams, draws, resultados, publicados, pedidosDesencontro, clubesExtra });
        const ok = await window.storage.set(STORAGE_KEY, payload, true);
        setEstadoGravacao(ok ? `Guardado às ${new Date().toLocaleTimeString("pt-PT")}` : "Falha ao guardar");
      } catch (e) {
        console.error("Falha ao guardar estado:", e);
        setEstadoGravacao("Falha ao guardar");
      }
    }, 900);
    return () => clearTimeout(t);
  }, [teams, draws, resultados, publicados, pedidosDesencontro, carregado]);

  const registar = useCallback((clubeId, selecionadas, recinto, desencontrarDe) => {
    // selecionadas: [[competicaoId, quantidade], ...]
    setTeams((prev) => {
      const novas = [];
      let i = 0;
      selecionadas.forEach(([competicaoId, n]) => {
        for (let k = 0; k < n; k++) {
          novas.push({
            id: `t-${Date.now()}-${i++}`,
            clubeId,
            competicaoId,
            serie: null,
            equipaSeed: null,
            recinto: recinto || null,
            desencontrarDe: desencontrarDe && desencontrarDe.length ? desencontrarDe : null,
            data: new Date().toLocaleDateString("pt-PT"),
            estado: "Confirmada",
          });
        }
      });
      return [...prev, ...novas];
    });
  }, []);

  const onUpdateDraw = useCallback((compId, entry) => {
    setDraws((prev) => ({ ...prev, [compId]: entry }));
  }, []);

  const onSetResultado = useCallback((compId, fase, key, h, a) => {
    setResultados((prev) => ({
      ...prev,
      [compId]: { ...(prev[compId] || {}), [fase]: { ...(prev[compId]?.[fase] || {}), [key]: { h, a } } },
    }));
  }, []);

  const onTogglePublicar = useCallback((compId) => {
    setPublicados((prev) => ({ ...prev, [compId]: !prev[compId] }));
  }, []);

  const onAddPedido = useCallback((pedido) => {
    setPedidosDesencontro((prev) => [...prev, { ...pedido, id: `pd-${Date.now()}` }]);
  }, []);
  const onRemovePedido = useCallback((id) => {
    setPedidosDesencontro((prev) => prev.filter((p) => p.id !== id));
  }, []);

  // Retira uma equipa da prova por completo: apaga a inscrição e remove-a de
  // qualquer série/liga onde já estivesse colocada, recalculando o calendário.
  const removerEquipa = useCallback((teamId) => {
    setTeams((prev) => prev.filter((t) => t.id !== teamId));
    setDraws((prev) => {
      const next = { ...prev };
      Object.keys(next).forEach((compId) => {
        const entry = next[compId];
        if (entry.modo === "grupos" && entry.grupos.some((g) => g.some((t) => t.id === teamId))) {
          const grupos = entry.grupos.map((g) => g.filter((t) => t.id !== teamId));
          next[compId] = { modo: "grupos", grupos, calendario: buildCalendarioGrupos(compId, grupos.map((g) => g.map((t) => ({ id: t.id, clubeId: t.clubeId, equipa: t.equipa })))) };
        } else if (entry.modo === "liga" && entry.liga.some((t) => t.id === teamId)) {
          const liga = entry.liga.filter((t) => t.id !== teamId);
          next[compId] = { modo: "liga", liga, calendario: buildCalendarioLiga(compId, liga) };
        }
      });
      return next;
    });
  }, []);

  const onAddClube = useCallback((nome, concelhoId) => addClube(nome, concelhoId), []);

  const tabs = [
    { id: "inicio", label: "Início", icon: Shield },
    { id: "inscricao", label: "Inscrever equipa", icon: ClipboardList },
    { id: "publico", label: "Calendários", icon: CalendarDays },
    ...(modoGabinete
      ? [
          { id: "equipas", label: "Equipas inscritas", icon: Users },
          { id: "quadros", label: "Quadros competitivos", icon: LayoutGrid },
          { id: "calendario", label: "Calendário (gestão)", icon: CalendarDays },
        ]
      : []),
  ];

  return (
    <div className="pf-body min-h-screen w-full" style={{ backgroundColor: T.bg }}>
      <style>{FONT_CSS}</style>
      <header className="border-b" style={{ borderColor: T.line, backgroundColor: T.surface }}>
        <div className="mx-auto flex max-w-6xl items-center gap-3 px-5 py-4">
          <img src={LOGO_SRC} alt="Distrital Pro" className="h-11 w-11 shrink-0 rounded-lg object-cover" style={{ boxShadow: "0 4px 14px -4px rgba(193,60,75,.65)" }} />
          <div className="flex-1">
            <p className="pf-display text-base font-semibold leading-tight" style={{ color: T.text }}>
              <span style={{ color: T.text }}>Distrital</span><span style={{ color: T.brand }}>Pro</span>
            </p>
            <p className="pf-body text-xs" style={{ color: T.text3 }}>
              {modoGabinete ? "Gabinete Técnico · AF Beja · Época 2026/2027" : "AF Beja · A tua prova. O teu clube. O teu distrito."}
            </p>
          </div>
          {modoGabinete && (
            <div className="pf-mono hidden text-right text-[11px] sm:block" style={{ color: T.text3 }}>
              {estadoGravacao || "A carregar…"}
            </div>
          )}
          {modoGabinete ? (
            <>
              <button onClick={sairGabinete} className="pf-body pf-focus rounded-md border px-3 py-1.5 text-xs font-semibold" style={{ borderColor: T.line, color: T.text2 }}>
                Sair do Gabinete Técnico
              </button>
            </>
          ) : mostrarLogin ? (
            <div className="flex items-center gap-1.5">
              <input
                type="password"
                autoFocus
                value={passwordInput}
                onChange={(e) => { setPasswordInput(e.target.value); setErroLogin(false); }}
                onKeyDown={(e) => e.key === "Enter" && tentarEntrar()}
                placeholder="Palavra-passe"
                className="pf-body pf-focus w-32 rounded-md border px-2 py-1.5 text-xs"
                style={{ borderColor: erroLogin ? T.danger : T.line, color: T.text, backgroundColor: T.surface2 }}
              />
              <button onClick={tentarEntrar} className="pf-body pf-focus rounded-md px-2.5 py-1.5 text-xs font-semibold" style={{ backgroundColor: T.brand, color: "#FFFFFF" }}>Entrar</button>
              <button onClick={() => { setMostrarLogin(false); setPasswordInput(""); setErroLogin(false); }} className="pf-focus" style={{ color: T.text3 }}><X size={16} /></button>
            </div>
          ) : (
            <button onClick={() => setMostrarLogin(true)} className="pf-body pf-focus rounded-md border px-3 py-1.5 text-xs font-semibold" style={{ borderColor: T.line, color: T.text2 }}>
              Acesso Gabinete Técnico
            </button>
          )}
        </div>
        <nav className="mx-auto flex max-w-6xl gap-1 overflow-x-auto px-5">
          {tabs.map((t) => {
            const Icon = t.icon;
            const active = tab === t.id;
            return (
              <button key={t.id} onClick={() => setTab(t.id)} className="pf-tab-btn pf-body flex shrink-0 items-center gap-1.5 border-b-2 px-3 py-2.5 text-sm font-medium" style={{ borderColor: active ? T.brand : "transparent", color: active ? T.text : T.text3 }}>
                <Icon size={15} /> {t.label} {active && <ChevronRight size={13} style={{ color: T.brand }} />}
              </button>
            );
          })}
        </nav>
      </header>

      <main className="mx-auto max-w-6xl px-5 py-8">
        {tab === "inicio" && <LandingPage teamsLabeled={teamsLabeled} draws={draws} publicados={publicados} onNavigate={setTab} />}
        {tab === "inscricao" && <InscricaoTab teamsLabeled={teamsLabeled} onRegister={registar} onAddClube={onAddClube} modoGabinete={modoGabinete} pedidosDesencontro={pedidosDesencontro} onAddPedido={onAddPedido} onRemovePedido={onRemovePedido} />}
        {tab === "publico" && <CalendarioTab teamsLabeled={teamsLabeled} draws={draws} resultados={resultados} publicados={publicados} modoPublico onExportarPDF={setPrintRequest} pedidosDesencontro={pedidosDesencontro} />}
        {modoGabinete && tab === "equipas" && <EquipasTab teamsLabeled={teamsLabeled} onRemoveEquipa={removerEquipa} onExportarPDF={setPrintRequest} />}
        {modoGabinete && tab === "quadros" && <QuadrosTab teamsLabeled={teamsLabeled} draws={draws} onUpdateDraw={onUpdateDraw} onRemoveEquipa={removerEquipa} resultados={resultados} onExportarPDF={setPrintRequest} />}
        {modoGabinete && tab === "calendario" && <CalendarioTab teamsLabeled={teamsLabeled} draws={draws} resultados={resultados} onSetResultado={onSetResultado} publicados={publicados} onTogglePublicar={onTogglePublicar} onExportarPDF={setPrintRequest} pedidosDesencontro={pedidosDesencontro} />}
      </main>
      {printRequest && <RelatorioPDF request={printRequest} onClose={() => setPrintRequest(null)} />}
    </div>
  );
}
